//! String.prototype.localeCompare without a locale or with "en", and the
//! default options: the CLDR root collation of ICU, as V8 gives it.
//!
//! Both texts go to NFD (`normalize.zig`; V8 turns normalization on). Each
//! takes its collation elements from `collate_tables.zig` (generated by
//! `gen_collate.mjs` from CLDR 48): the longest contraction first, then the
//! unblocked combining marks that extend it (UCA S2.1), else the implicit
//! weights (Han in radical-stroke order, siniform scripts, other code
//! points). The comparison goes level by level: primary, secondary, tertiary
//! weights, each without the zero weights. Variable elements are not
//! ignorable, as in ICU's default.
//!
//! The element arrays live in the arena; all loops are bounded by the text.
const std = @import("std");
const tables = @import("collate_tables.zig");
const ntables = @import("normalize_tables.zig");
const unorm = @import("normalize.zig");
const Arena = @import("arena.zig").Arena;
const assert = std.debug.assert;

const CE = tables.CE;

/// The most elements that one code point or contraction gives.
const max_expansion = 18;

fn primary(ce: CE) u32 {
    return ce >> 14;
}

fn ceOf(p: u32, s: u32, t: u32) CE {
    return (p << 14) | (s << 5) | t;
}

fn single(cp: u32) ?[]const CE {
    var lo: usize = 0;
    var hi: usize = tables.singles.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const rec = tables.singles[mid];
        const c: u32 = @intCast(rec >> 32);
        if (c == cp) {
            const start: usize = @intCast((rec >> 8) & 0xFFFFFF);
            const len: usize = @intCast(rec & 0xFF);
            return tables.pool[start..][0..len];
        }
        if (c < cp) lo = mid + 1 else hi = mid;
    }
    return null;
}

fn contraction(a: u32, b: u32, c: u32) ?[]const CE {
    const key = (@as(u64, a) << 42) | (@as(u64, b) << 21) | c;
    var lo: usize = 0;
    var hi: usize = tables.contraction_keys.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const k = tables.contraction_keys[mid];
        if (k == key) {
            const v = tables.contraction_values[mid];
            return tables.pool[v >> 8 ..][0 .. v & 0xFF];
        }
        if (k < key) lo = mid + 1 else hi = mid;
    }
    return null;
}

fn class(cp: u32) u8 {
    var lo: usize = 0;
    var hi: usize = ntables.classes.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const e = ntables.classes[mid];
        if (e.cp == cp) return e.class;
        if (e.cp < cp) lo = mid + 1 else hi = mid;
    }
    return 0;
}

fn hanRank(cp: u32) ?u32 {
    var lo: usize = 0;
    var hi: usize = tables.han_runs.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const rec = tables.han_runs[mid];
        const first: u32 = @intCast(rec >> 33);
        const len: u32 = @intCast((rec >> 17) & 0xFFFF);
        if (cp >= first and cp < first + len) return @as(u32, @intCast(rec & 0x1FFFF)) + (cp - first);
        if (first < cp) lo = mid + 1 else hi = mid;
    }
    return null;
}

/// The two implicit elements of a code point that the table does not list.
fn implicit(cp: u32) [2]CE {
    if (hanRank(cp)) |r| return .{ ceOf(0xFB40 + (r >> 15), 0x20, 2), ceOf((r & 0x7FFF) | 0x8000, 0, 0) };
    for (tables.siniform) |s| {
        if (cp >= s.lo and cp <= s.hi) return .{ ceOf(s.base, 0x20, 2), ceOf((cp - s.first) | 0x8000, 0, 0) };
    }
    return .{ ceOf(0xFBC0 + (cp >> 15), 0x20, 2), ceOf((cp & 0x7FFF) | 0x8000, 0, 0) };
}

/// The code points of `bytes` in NFD; a lone surrogate (WTF-8) is its code unit.
fn codePoints(arena: *Arena, bytes: []const u8) Arena.Error![]u32 {
    var ascii = true;
    for (bytes) |c| {
        if (c >= 0x80) ascii = false;
    }
    const nfd = if (ascii) bytes else try unorm.normalize(arena, bytes, .nfd);
    const out = try arena.push(u32, nfd.len);
    var n: usize = 0;
    var i: usize = 0;
    while (i < nfd.len) {
        const lead = nfd[i];
        const len: usize = if (lead < 0x80) 1 else if (lead < 0xE0) 2 else if (lead < 0xF0) 3 else 4;
        if (len == 1 or i + len > nfd.len) {
            out[n] = lead;
            i += 1;
        } else {
            var cp: u32 = lead & (@as(u8, 0x7F) >> @intCast(len));
            for (nfd[i + 1 .. i + len]) |c| cp = (cp << 6) | (c & 0x3F);
            out[n] = cp;
            i += len;
        }
        n += 1;
    }
    return out[0..n];
}

/// The first index after `k` that no contraction took.
fn nextFree(taken: []const bool, k: usize) usize {
    var j = k + 1;
    while (j < taken.len and taken[j]) j += 1;
    return j;
}

/// The collation elements of `text`, in the arena.
fn elements(arena: *Arena, text: []const u8) Arena.Error![]const CE {
    const s = try codePoints(arena, text);
    const out = try arena.push(CE, s.len * max_expansion + 2);
    // Code points that a contraction took, contiguous or not.
    const taken = try arena.push(bool, s.len);
    @memset(taken, false);
    var n: usize = 0;
    var i: usize = 0;
    while (i < s.len) : (i += 1) {
        if (taken[i]) continue;
        const second = nextFree(taken, i);
        const third = if (second < s.len) nextFree(taken, second) else s.len;
        // The longest contiguous match: three, two, then one code point.
        var len: usize = 1;
        var key: [3]u32 = .{ s[i], 0, 0 };
        var ces: ?[]const CE = null;
        if (third < s.len) {
            if (contraction(s[i], s[second], s[third])) |c| {
                ces = c;
                len = 3;
                key = .{ s[i], s[second], s[third] };
                taken[second] = true;
                taken[third] = true;
            }
        }
        if (ces == null and second < s.len) {
            if (contraction(s[i], s[second], 0)) |c| {
                ces = c;
                len = 2;
                key = .{ s[i], s[second], 0 };
                taken[second] = true;
            }
        }
        if (ces == null) ces = single(s[i]);
        // Discontiguous: unblocked non-starters after the match that extend it (UCA S2.1).
        if (len < 3) {
            var j = nextFree(taken, i);
            var last_class: u8 = 0;
            while (j < s.len) : (j = nextFree(taken, j)) {
                const c = class(s[j]);
                if (c == 0) break;
                if (last_class == 0 or last_class < c) {
                    const ext = if (len == 1) contraction(key[0], s[j], 0) else contraction(key[0], key[1], s[j]);
                    if (ext) |e| {
                        ces = e;
                        key[len] = s[j];
                        taken[j] = true;
                        len += 1;
                        if (len == 3) break;
                        continue;
                    }
                }
                last_class = c;
            }
        }
        if (ces) |c| {
            assert(c.len <= max_expansion);
            @memcpy(out[n..][0..c.len], c);
            n += c.len;
        } else {
            const imp = implicit(s[i]);
            out[n] = imp[0];
            out[n + 1] = imp[1];
            n += 2;
        }
    }
    return out[0..n];
}

fn weight(ce: CE, level: u2) u32 {
    return switch (level) {
        0 => ce >> 14,
        1 => (ce >> 5) & 0x1FF,
        else => ce & 0x1F,
    };
}

/// -1, 0 or 1: the order of `a` and `b` in the CLDR root collation.
pub fn compare(arena: *Arena, a: []const u8, b: []const u8) Arena.Error!i8 {
    const t = arena.begin();
    defer t.end();
    const ea = try elements(arena, a);
    const eb = try elements(arena, b);
    var level: u2 = 0;
    while (level < 3) : (level += 1) {
        var i: usize = 0;
        var j: usize = 0;
        while (true) {
            while (i < ea.len and weight(ea[i], level) == 0) i += 1;
            while (j < eb.len and weight(eb[j], level) == 0) j += 1;
            if (i == ea.len or j == eb.len) {
                if (i == ea.len and j == eb.len) break;
                return if (i == ea.len) -1 else 1;
            }
            const wa = weight(ea[i], level);
            const wb = weight(eb[j], level);
            if (wa != wb) return if (wa < wb) -1 else 1;
            i += 1;
            j += 1;
        }
    }
    return 0;
}

const testing = std.testing;

fn appendHex(list: *std.ArrayList(u8), gpa: std.mem.Allocator, field: []const u8) !void {
    var it = std.mem.tokenizeScalar(u8, field, ' ');
    while (it.next()) |h| {
        const cp = try std.fmt.parseInt(u21, h, 16);
        var enc: [4]u8 = undefined;
        const len = try std.unicode.utf8Encode(cp, &enc);
        try list.appendSlice(gpa, enc[0..len]);
    }
}

test "compares as Node.js does" {
    const gpa = testing.allocator;
    const text = @embedFile("testdata/collate_cases.txt");
    const buf = try gpa.alloc(u8, 1 << 20);
    defer gpa.free(buf);
    var arena = Arena.init(buf);
    var a: std.ArrayList(u8) = .empty;
    defer a.deinit(gpa);
    var b: std.ArrayList(u8) = .empty;
    defer b.deinit(gpa);
    var lines = std.mem.tokenizeScalar(u8, text, '\n');
    var count: usize = 0;
    var bad: usize = 0;
    while (lines.next()) |line| {
        var cols = std.mem.splitScalar(u8, line, '\t');
        a.clearRetainingCapacity();
        b.clearRetainingCapacity();
        try appendHex(&a, gpa, cols.next() orelse return error.BadCase);
        try appendHex(&b, gpa, cols.next() orelse return error.BadCase);
        const want = try std.fmt.parseInt(i8, cols.next() orelse return error.BadCase, 10);
        const got = try compare(&arena, a.items, b.items);
        if (got != want) {
            bad += 1;
            if (bad <= 5) std.debug.print("{s}: want {d}, got {d}\n", .{ line, want, got });
        }
        count += 1;
    }
    try testing.expectEqual(@as(usize, 0), bad);
    try testing.expect(count > 10000);
}
